const input = $input.first().json;

// Preserve normalized input
const message = (input.message ?? '').toString().trim();
const customerName = (input.customer_name ?? '').toString().trim();
const email = (input.email ?? '').toString().trim();

// Generate conversation ID only if caller did not provide one
const conversationId =
  (input.conversation_id ?? '').toString().trim() ||
  `conv_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

// Small approved FAQ knowledge base for Project 2.
// The LLM may answer FAQ questions only from these enabled entries.
const faqKnowledge = [
  {
    key: "FAQ_SERVICES",
    topic: "Services offered",
    approved_answer:
      "We provide n8n workflow automation, OpenAI integrations, Google Workspace automation, API integrations, and AI-assisted business workflows.",
    enabled: true
  },
  {
    key: "FAQ_SUPPORTED_INTEGRATIONS",
    topic: "Supported integrations",
    approved_answer:
      "Supported integrations include n8n, OpenAI, Gmail, Google Sheets, Google Calendar, webhooks, and API-based services.",
    enabled: true
  },
  {
    key: "FAQ_PROCESS",
    topic: "Project process",
    approved_answer:
      "The typical process is requirements review, workflow design, implementation, testing, validation, and handover.",
    enabled: true
  },
  {
    key: "FAQ_HUMAN_REVIEW",
    topic: "Human review policy",
    approved_answer:
      "Consequential external communication and important operational decisions remain subject to human review.",
    enabled: true
  },
  {
    key: "FAQ_CONTACT",
    topic: "Human contact or escalation",
    approved_answer:
      "Requests that cannot be answered reliably can be escalated for human review.",
    enabled: true
  }
];

return [
  {
    json: {
      conversation_id: conversationId,
      message,
      customer_name: customerName || null,
      email: email || null,
      received_at: input.received_at,

      allowed_intents: [
        "sales",
        "support",
        "faq",
        "unknown"
      ],

      confidence_policy: {
        normal_routing_min: 0.80,
        clarification_min: 0.60,
        faq_answer_min: 0.85
      },

      faq_knowledge: faqKnowledge,

      allowed_faq_keys: faqKnowledge
        .filter(item => item.enabled)
        .map(item => item.key),

      business_context_version: "project2_v1"
    }
  }
];

