parameters.jsCode:
const raw = $input.first()?.json ?? {};

// Recover the prepared customer/business context from the earlier node.
let prepared = {};
try {
  prepared = $('Prepare AI Request').first().json ?? {};
} catch (e) {
  prepared = {};
}

const errors = [];

const isObject = (value) =>
  value !== null &&
  typeof value === 'object' &&
  !Array.isArray(value);

const isNullableString = (value) =>
  value === null || typeof value === 'string';

const isNullableNumber = (value) =>
  value === null ||
  (typeof value === 'number' && Number.isFinite(value));

const allowedIntents = new Set(
  prepared.allowed_intents ?? ['sales', 'support', 'faq', 'unknown']
);

const allowedUrgency = new Set([
  'low',
  'medium',
  'high',
  'unknown'
]);

const allowedScopeClarity = new Set([
  'low',
  'medium',
  'high',
  'unknown'
]);

const allowedBusinessImpact = new Set([
  'none',
  'low',
  'medium',
  'high',
  'critical',
  'unknown'
]);

const allowedFaqKeys = new Set(
  prepared.allowed_faq_keys ?? []
);

// Exact structure confirmed from the OpenAI node test.
const aiMessage = raw?.output?.[0] ?? null;
const analysis =
  raw?.output?.[0]?.content?.[0]?.text ?? null;

const aiMessageId = aiMessage?.id ?? null;

// ---------- Top-level validation ----------

if (!isObject(analysis)) {
  errors.push('missing_or_invalid_structured_output');
}

if (isObject(analysis)) {
  if (!allowedIntents.has(analysis.intent)) {
    errors.push('invalid_intent');
  }

  if (
    typeof analysis.intent_confidence !== 'number' ||
    !Number.isFinite(analysis.intent_confidence) ||
    analysis.intent_confidence < 0 ||
    analysis.intent_confidence > 1
  ) {
    errors.push('invalid_intent_confidence');
  }

  if (typeof analysis.summary !== 'string') {
    errors.push('invalid_summary');
  }

  // ---------- Sales ----------
  if (!isObject(analysis.sales)) {
    errors.push('invalid_sales_object');
  } else {
    const sales = analysis.sales;

    if (!isNullableString(sales.service_requested)) {
      errors.push('invalid_service_requested');
    }

    if (
      !isNullableNumber(sales.budget_eur) ||
      (typeof sales.budget_eur === 'number' && sales.budget_eur < 0)
    ) {
      errors.push('invalid_budget_eur');
    }

    if (typeof sales.deadline_present !== 'boolean') {
      errors.push('invalid_deadline_present');
    }

    if (!isNullableString(sales.deadline_text)) {
      errors.push('invalid_deadline_text');
    }

    if (!allowedUrgency.has(sales.urgency_signal)) {
      errors.push('invalid_urgency_signal');
    }

    if (!allowedScopeClarity.has(sales.scope_clarity)) {
      errors.push('invalid_scope_clarity');
    }
  }

  // ---------- Support ----------
  if (!isObject(analysis.support)) {
    errors.push('invalid_support_object');
  } else {
    const support = analysis.support;

    if (!isNullableString(support.problem_type)) {
      errors.push('invalid_problem_type');
    }

    if (typeof support.service_down !== 'boolean') {
      errors.push('invalid_service_down');
    }

    if (typeof support.data_loss_reported !== 'boolean') {
      errors.push('invalid_data_loss_reported');
    }

    if (typeof support.security_related !== 'boolean') {
      errors.push('invalid_security_related');
    }

    if (!allowedBusinessImpact.has(support.business_impact)) {
      errors.push('invalid_business_impact');
    }
  }

  // ---------- FAQ ----------
  if (!isObject(analysis.faq)) {
    errors.push('invalid_faq_object');
  } else {
    const faq = analysis.faq;

    if (!isNullableString(faq.topic)) {
      errors.push('invalid_faq_topic');
    }

    if (!isNullableString(faq.faq_source_key)) {
      errors.push('invalid_faq_source_key_type');
    }

    if (typeof faq.answer_supported !== 'boolean') {
      errors.push('invalid_answer_supported');
    }

    if (!isNullableString(faq.answer)) {
      errors.push('invalid_faq_answer');
    }

    // The model may only reference an approved enabled FAQ key.
    if (
      faq.faq_source_key !== null &&
      !allowedFaqKeys.has(faq.faq_source_key)
    ) {
      errors.push('unapproved_faq_source_key');
    }

    // A supported FAQ answer requires both a valid source key and answer.
    if (faq.answer_supported === true) {
      if (
        faq.faq_source_key === null ||
        !allowedFaqKeys.has(faq.faq_source_key)
      ) {
        errors.push('supported_faq_without_valid_source');
      }

      if (
        typeof faq.answer !== 'string' ||
        faq.answer.trim().length === 0
      ) {
        errors.push('supported_faq_without_answer');
      }
    }
  }

  // ---------- Other required fields ----------
  if (
    !Array.isArray(analysis.missing_information) ||
    !analysis.missing_information.every(
      (item) => typeof item === 'string'
    )
  ) {
    errors.push('invalid_missing_information');
  }

  if (typeof analysis.human_requested !== 'boolean') {
    errors.push('invalid_human_requested');
  }

  if (typeof analysis.possible_prompt_injection !== 'boolean') {
    errors.push('invalid_prompt_injection_flag');
  }

  if (typeof analysis.proposed_response !== 'string') {
    errors.push('invalid_proposed_response');
  }
}

const aiOutputValid = errors.length === 0;

// Safe fallback prevents bad AI output from entering normal routing.
const safeFallback = {
  intent: 'unknown',
  intent_confidence: 0,
  summary: 'AI output could not be validated.',
  sales: {
    service_requested: null,
    budget_eur: null,
    deadline_present: false,
    deadline_text: null,
    urgency_signal: 'unknown',
    scope_clarity: 'unknown'
  },
  support: {
    problem_type: null,
    service_down: false,
    data_loss_reported: false,
    security_related: false,
    business_impact: 'unknown'
  },
  faq: {
    topic: null,
    faq_source_key: null,
    answer_supported: false,
    answer: null
  },
  missing_information: [],
  human_requested: false,
  possible_prompt_injection: false,
  proposed_response:
    'I could not process this request reliably. It has been flagged for human review.'
};

const normalizedAnalysis =
  aiOutputValid ? analysis : safeFallback;

return [
  {
    json: {
      ...prepared,

      ai_message_id: aiMessageId,
      ai_output_valid: aiOutputValid,
      validation_errors: errors,

      ...normalizedAnalysis
    }
  }
];

const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const sales = data.sales ?? {};

  const budget = Number(sales.budget_eur ?? 0);
  const deadlinePresent = sales.deadline_present === true;

  const urgency = String(
    sales.urgency_signal ?? "unknown"
  ).toLowerCase();

  const scopeClarity = String(
    sales.scope_clarity ?? "unknown"
  ).toLowerCase();

  const intentConfidence = Number(
    data.intent_confidence ?? 0
  );

  let leadScore = 0;

  // -------------------------
  // Budget score: max 30
  // -------------------------
  if (budget >= 5000) {
    leadScore += 30;
  } else if (budget >= 2000) {
    leadScore += 20;
  } else if (budget > 0) {
    leadScore += 10;
  }

  // -------------------------
  // Sales intent confidence: max 25
  // -------------------------
  if (intentConfidence >= 0.9) {
    leadScore += 25;
  } else if (intentConfidence >= 0.8) {
    leadScore += 15;
  }

  // -------------------------
  // Deadline: max 20
  // -------------------------
  if (deadlinePresent) {
    leadScore += 20;
  }

  // -------------------------
  // Scope clarity: max 15
  // -------------------------
  if (scopeClarity === "high") {
    leadScore += 15;
  } else if (scopeClarity === "medium") {
    leadScore += 10;
  }

  // -------------------------
  // Urgency: max 10
  // -------------------------
  if (urgency === "high") {
    leadScore += 10;
  } else if (urgency === "medium") {
    leadScore += 5;
  }

  // Keep within 0-100
  leadScore = Math.min(100, leadScore);

  // -------------------------
  // Deterministic qualification
  // -------------------------
  const salesQualified =
    budget >= 2000 &&
    intentConfidence >= 0.8 &&
    leadScore >= 60;

  return {
    json: {
      ...data,

      lead_score: leadScore,

      sales_qualified: salesQualified,

      sales_route: salesQualified
        ? "high_value"
        : "normal"
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const support = data.support ?? {};

  const serviceDown = support.service_down === true;
  const dataLoss = support.data_loss_reported === true;
  const securityRelated = support.security_related === true;

  const businessImpact = String(
    support.business_impact ?? "unknown"
  ).toLowerCase();

  let supportScore = 0;

  // Security-related issue
  if (securityRelated) {
    supportScore += 40;
  }

  // Reported data loss
  if (dataLoss) {
    supportScore += 30;
  }

  // Service unavailable
  if (serviceDown) {
    supportScore += 20;
  }

  // Business impact
  if (
    businessImpact === "critical" ||
    businessImpact === "high"
  ) {
    supportScore += 10;
  } else if (businessImpact === "medium") {
    supportScore += 5;
  }

  supportScore = Math.min(100, supportScore);

  let supportPriority = "normal";

  if (
    securityRelated ||
    dataLoss ||
    businessImpact === "critical" ||
    supportScore >= 50
  ) {
    supportPriority = "critical";
  } else if (
    serviceDown ||
    businessImpact === "high" ||
    supportScore >= 20
  ) {
    supportPriority = "high";
  }

  return {
    json: {
      ...data,
      support_score: supportScore,
      support_priority: supportPriority,
      support_escalation_required:
        supportPriority === "critical" ||
        supportPriority === "high"
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const faq = data.faq ?? {};

  const intentConfidence = Number(data.intent_confidence ?? 0);

  const faqThreshold = Number(
    data.confidence_policy?.faq_answer_min ?? 0.85
  );

  const faqKey = faq.faq_source_key ?? null;

  const allowedKeys = Array.isArray(data.allowed_faq_keys)
    ? data.allowed_faq_keys
    : [];

  const knowledge = Array.isArray(data.faq_knowledge)
    ? data.faq_knowledge
    : [];

  const matchedFaq = knowledge.find(
    (entry) =>
      entry.key === faqKey &&
      entry.enabled === true
  );

  const keyAllowed =
    faqKey !== null &&
    allowedKeys.includes(faqKey);

  const validKnowledgeSource =
    keyAllowed &&
    matchedFaq !== undefined;

  const confidencePassed =
    intentConfidence >= faqThreshold;

  const modelSaysSupported =
    faq.answer_supported === true;

  const safeRequest =
    data.possible_prompt_injection !== true;

  const humanNotExplicitlyRequested =
    data.human_requested !== true;

  const faqAutoAnswerAllowed =
    data.intent === "faq" &&
    confidencePassed &&
    modelSaysSupported &&
    validKnowledgeSource &&
    safeRequest &&
    humanNotExplicitlyRequested;

  let validationReason = "FAQ requires human review";

  if (faqAutoAnswerAllowed) {
    validationReason = "FAQ matched an enabled approved knowledge source";
  } else if (!confidencePassed) {
    validationReason = "FAQ confidence below automatic-answer threshold";
  } else if (!modelSaysSupported) {
    validationReason = "Model marked FAQ answer as unsupported";
  } else if (!keyAllowed) {
    validationReason = "FAQ source key is not allowed";
  } else if (!validKnowledgeSource) {
    validationReason = "FAQ source key did not match enabled knowledge";
  } else if (!safeRequest) {
    validationReason = "Possible prompt injection detected";
  } else if (!humanNotExplicitlyRequested) {
    validationReason = "Customer explicitly requested human assistance";
  }

  return {
    json: {
      ...data,

      faq_auto_answer_allowed: faqAutoAnswerAllowed,

      faq_route: faqAutoAnswerAllowed
        ? "approved_answer"
        : "human_fallback",

      faq_answer_text: faqAutoAnswerAllowed
        ? matchedFaq.approved_answer
        : null,

      faq_validation_reason: validationReason
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const confidence = Number(data.intent_confidence ?? 0);

  const normalMin = Number(
    data.confidence_policy?.normal_routing_min ?? 0.8
  );

  const clarificationMin = Number(
    data.confidence_policy?.clarification_min ?? 0.6
  );

  let routingConfidenceBand = "low";
  let automatedIntentRoutingAllowed = false;

  if (confidence >= normalMin) {
    routingConfidenceBand = "normal";
    automatedIntentRoutingAllowed = true;
  } else if (confidence >= clarificationMin) {
    routingConfidenceBand = "clarification";
  }

  // Prompt-injection flags should prevent operational auto-routing
  if (data.possible_prompt_injection === true) {
    automatedIntentRoutingAllowed = false;
    routingConfidenceBand = "human_fallback";
  }

  return {
    json: {
      ...data,
      routing_confidence_band: routingConfidenceBand,
      automated_intent_routing_allowed: automatedIntentRoutingAllowed
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const band = String(
    data.routing_confidence_band ?? "low"
  ).toLowerCase();

  const confidence = Number(
    data.intent_confidence ?? 0
  );

  const promptInjection =
    data.possible_prompt_injection === true;

  let workflowRoute;
  let priority;
  let requiresHumanReview;
  let draftNeeded;
  let responseText;
  let decisionReason;

  if (band === "clarification") {
    workflowRoute = "routing_clarification";
    priority = "normal";
    requiresHumanReview = false;
    draftNeeded = false;

    responseText =
      "I’m not confident enough to determine the correct request type. Could you provide a little more detail about what you need help with?";

    decisionReason =
      `Intent confidence ${confidence} is below the automatic-routing threshold.`;

  } else {
    workflowRoute = "routing_human_fallback";
    priority = promptInjection ? "high" : "normal";
    requiresHumanReview = true;
    draftNeeded = true;

    responseText =
      "I’m unable to route this request reliably. It will be sent for human review.";

    decisionReason = promptInjection
      ? "Possible prompt injection detected; automated routing blocked."
      : `Intent confidence ${confidence} is too low for automated routing.`;
  }

  return {
    json: {
      ...data,
      workflow_route: workflowRoute,
      priority,
      requires_human_review: requiresHumanReview,
      draft_needed: draftNeeded,
      response_text: responseText,
      decision_reason: decisionReason
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const d = item.json;

  const route = d.workflow_route ?? "unclassified";
  const draftNeeded = d.draft_needed === true;

  let draftSubject = d.draft_subject ?? null;

  if (draftNeeded && !draftSubject) {
    if (route === "faq_human_fallback") {
      draftSubject = "Re: Your question";
    } else if (route === "routing_human_fallback") {
      draftSubject = "Review required: customer request";
    } else {
      draftSubject = "Re: Customer request";
    }
  }

  return {
    json: {
      conversation_id: d.conversation_id ?? null,
      received_at: d.received_at ?? null,

      customer_name: d.customer_name ?? null,
      email: d.email ?? null,
      original_message: d.message ?? null,

      intent: d.intent ?? null,
      intent_confidence: d.intent_confidence ?? null,
      routing_confidence_band: d.routing_confidence_band ?? null,

      summary: d.summary ?? null,

      workflow_route: route,
      priority: d.priority ?? "normal",

      requires_human_review:
        d.requires_human_review === true,

      draft_needed: draftNeeded,

      response_text:
        d.response_text ??
        d.proposed_response ??
        null,

      decision_reason:
        d.decision_reason ??
        null,

      lead_score:
        d.lead_score ?? null,

      support_score:
        d.support_score ?? null,

      support_priority:
        d.support_priority ?? null,

      faq_route:
        d.faq_route ?? null,

      draft_to:
        draftNeeded
          ? (d.draft_to ?? d.email ?? null)
          : null,

      draft_subject:
        draftNeeded
          ? draftSubject
          : null,

      draft_body:
        draftNeeded
          ? (d.draft_body ?? d.response_text ?? d.proposed_response ?? null)
          : null,

      draft_status:
        draftNeeded
          ? (d.draft_status ?? "pending_human_review")
          : "not_required",

      ai_message_id:
        d.ai_message_id ?? null
    }
  };
});

